1	import { Router, type IRouter } from "express";
2	import { eq, and, or, sql, ne, inArray } from "drizzle-orm";
3	import { db, bookingsTable, courtsTable, courtBlockedSlotsTable, facilitiesTable, waitlistsTable, gamesTable, gameParticipantsTable, coachesTable, coachReviewsTable, reviewsTable } from "@workspace/db";
4	import { buildDayPriceMap } from "../lib/pricing";
5	import { sendNotification } from "../lib/notify";
6	import { sendCustomerCancellationEmail, sendOwnerCancellationEmail, sendWaitlistNotificationEmail } from "../lib/email";
7	import {
8	  ListBookingsQueryParams,
