22	// Cryptographically random opaque token used to authorize guest booking management.
23	export function generateManagementToken(): string {
24	  return randomBytes(32).toString("base64url");
25	}
26	
27	// ─── Refund tier policy ──────────────────────────────────────────────────────
28	//
29	// COURT policy (`facilities.cancellationPolicy`):
30	//   'standard' (default)
31	//     >= 48h before start: 80% refund
32	//     >= 24h and < 48h:    50% refund
33	//     <  24h:              0% refund
34	//   'strict':  0% at any time
35	//
36	// COACH policy (`coaches.cancellationPolicy`):
37	//   'flexible': 100% up to 24h before start; 0% inside 24h.
38	//   'standard': matches the court 80/50/0 tiers above.
39	//   'strict':   0% at any time.
40	//
41	// All money math is done in INTEGER CENTS to avoid binary-float drift (e.g.
42	// 19.99 * 0.5 = 9.995). Stripe APIs accept amounts in integer cents.
43	//
44	// CRITICAL INVARIANT (Strike 3): for any cancellation, the total refunded to
45	// the player is computeCourtRefundCents() + computeCoachRefundCents() with NO
46	// further adjustment. The platform retains its full margin to cover Stripe's
47	// non-refundable processing fees.
48	
49	export type CourtCancellationPolicy = "standard" | "strict";
50	export type CoachCancellationPolicy = "flexible" | "standard" | "strict";
51	
52	function standardTierPercent(hours: number): number {
53	  if (hours >= 48) return 80;
54	  if (hours >= 24) return 50;
55	  return 0;
56	}
57	
58	export function computeCourtRefundCents(
59	  courtCents: number,
60	  hours: number,
61	  policy: CourtCancellationPolicy,
62	): number {
63	  if (policy === "strict") return 0;
64	  const pct = standardTierPercent(hours);
65	  if (pct === 0) return 0;
66	  return Math.round((courtCents * pct) / 100);
67	}
68	
69	export function computeCoachRefundCents(
70	  coachCents: number,
71	  hours: number,
72	  policy: CoachCancellationPolicy,
73	): number {
74	  if (coachCents <= 0) return 0;
75	  if (policy === "strict") return 0;
76	  if (policy === "flexible") return hours >= 24 ? coachCents : 0;
77	  const pct = standardTierPercent(hours);
78	  if (pct === 0) return 0;
79	  return Math.round((coachCents * pct) / 100);
80	}
81	
82	// Backwards-compatible wrapper retained for guest-bookings, games (split), and
83	// diagnostic routes that don't yet split court vs. coach. New code should call
84	// computeCourtRefundCents directly.
85	export function computeRefund(
86	  totalPriceEur: number,
87	  hoursBeforeStart: number,
88	  policy: CourtCancellationPolicy = "standard",
89	) {
90	  const totalCents = Math.round(totalPriceEur * 100);
91	  const cents = computeCourtRefundCents(totalCents, hoursBeforeStart, policy);
92	  const pct = policy === "strict" ? 0 : standardTierPercent(hoursBeforeStart);
93	  return {
94	    refundPercent: pct,
95	    refundAmount: cents / 100,
96	    refundCents: cents,
97	    refundable: cents > 0,
98	  };
99	}
100	
101	// Booking `date`/`startTime` are stored as Lithuanian local time strings. The
102	// server runs in UTC, so naively parsing `${date}T${startTime}:00` would treat
103	// them as UTC and give a result that is wrong by Vilnius's DST offset (2–3h).
104	// Compute the UTC instant for the Vilnius wall-clock time, then diff against
105	// `Date.now()` in absolute milliseconds.
106	export function vilniusLocalToUtcMs(date: string, time: string): number {
107	  const dateOnly = String(date).slice(0, 10);
108	  // Step 1: pretend the local string is UTC.
109	  const naiveUtcMs = Date.parse(`${dateOnly}T${time}:00Z`);
110	  // Step 2: ask what Europe/Vilnius wall-clock that UTC instant displays.
111	  const fmt = new Intl.DateTimeFormat("en-GB", {
112	    timeZone: "Europe/Vilnius",
113	    year: "numeric", month: "2-digit", day: "2-digit",
114	    hour: "2-digit", minute: "2-digit", second: "2-digit",
115	    hour12: false,
116	  });
117	  const parts = fmt.formatToParts(new Date(naiveUtcMs));
118	  const get = (t: string) => parts.find(p => p.type === t)!.value;
119	  let hh = get("hour");
120	  if (hh === "24") hh = "00";
121	  const vilniusAsUtcMs = Date.UTC(
122	    Number(get("year")), Number(get("month")) - 1, Number(get("day")),
123	    Number(hh), Number(get("minute")), Number(get("second")),
124	  );
125	  // Offset = how many ms Vilnius is AHEAD of UTC at that instant (+2h or +3h).
126	  const offsetMs = vilniusAsUtcMs - naiveUtcMs;
127	  // Subtract offset to get the actual UTC instant for that Vilnius wall-clock time.
128	  return naiveUtcMs - offsetMs;
129	}
130	
131	export function hoursBeforeStart(date: string, startTime: string): number {
132	  return (vilniusLocalToUtcMs(date, startTime) - Date.now()) / (1000 * 60 * 60);
133	}
134	
135	// Returns the number of calendar days between today (Vilnius local) and the booking date.
136	function daysUntilBooking(dateStr: string): number {
137	  const fmt = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Vilnius" });
138	  const todayStr = fmt.format(new Date()); // YYYY-MM-DD
139	  const today = Date.parse(todayStr + "T00:00:00Z");
140	  const target = Date.parse(String(dateStr).slice(0, 10) + "T00:00:00Z");
141	  return Math.round((target - today) / (1000 * 60 * 60 * 24));
142	}
143	
144	function toMin(t: string): number {
145	  const [h, m] = t.split(":").map(Number);
146	  return h * 60 + m;
147	}
148	
149	function slotsBetween(startTime: string, endTime: string): string[] {
150	  const start = toMin(startTime);
151	  const end = toMin(endTime);
152	  const result: string[] = [];
153	  for (let m = start; m < end; m += 30) {
154	    const h = Math.floor(m / 60);
155	    const min = m % 60;
156	    result.push(`${h.toString().padStart(2, "0")}:${min.toString().padStart(2, "0")}`);
157	  }
158	  return result;
159	}
