163	function formatBooking(
164	  booking: typeof bookingsTable.$inferSelect,
165	  courtName?: string,
166	  paidSlots?: number,
167	  // Optional joined coach profile. Callers that LEFT JOIN coachesTable on
168	  // bookings.coachId = coachesTable.userId should pass { id, name } here so
169	  // the client doesn't N+1 fetch the coach to label the booking row.
170	  coach?: { id: number; name: string } | null,
171	  // The booker's existing review for this coach lesson, if any. Null when
172	  // none exists or this isn't a coach booking. Drives the player dashboard's
173	  // "Palikti atsiliepimą" → "Redaguoti atsiliepimą" CTA switch.
174	  coachReview?: { id: number; rating: number; comment: string | null } | null,
175	  // The booker's existing review for the court, if any. Populated regardless
176	  // of coach presence; the UI only surfaces the CTA for non-coach bookings
177	  // so players aren't asked to review a court and a coach lesson separately.
178	  courtReview?: { id: number; rating: number; comment: string | null } | null,
179	) {
180	  return {
181	    ...booking,
182	    totalPrice: Number(booking.totalPrice),
183	    refundAmount: Number(booking.refundAmount ?? 0),
184	    pricePerSlot: booking.pricePerSlot != null ? Number(booking.pricePerSlot) : undefined,
185	    totalSlots: booking.totalSlots ?? undefined,
186	    paidSlots: paidSlots,
187	    splitInviteToken: booking.splitInviteToken ?? undefined,
188	    rentedItems: booking.rentedItems ?? undefined,
189	    courtName: courtName ?? undefined,
190	    stripeSessionId: booking.stripeSessionId ?? undefined,
191	    stripePaymentIntentId: booking.stripePaymentIntentId ?? undefined,
192	    stripeRefundId: booking.stripeRefundId ?? undefined,
193	    managementToken: booking.managementToken ?? undefined,
194	    coach: coach ?? null,
195	    coachReview: coachReview ?? null,
196	    courtReview: courtReview ?? null,
197	  };
198	}
