200	router.get("/bookings", requireAuth, async (req, res): Promise<void> => {
201	  const params = ListBookingsQueryParams.safeParse(req.query);
202	  if (!params.success) {
203	    res.status(400).json({ error: params.error.message });
204	    return;
205	  }
206	
207	  const userId = getCurrentUserId(req)!;
208	  const role = await getUserRole(userId);
209	
210	  const conditions = [];
211	  if (params.data.courtId != null) {
212	    conditions.push(eq(bookingsTable.courtId, params.data.courtId));
213	  }
214	  if (params.data.status) {
215	    conditions.push(eq(bookingsTable.status, params.data.status));
216	  }
217	  if (params.data.customerEmail) {
218	    conditions.push(eq(bookingsTable.customerEmail, params.data.customerEmail));
219	  }
220	
221	  let query = db
222	    .select({
223	      booking: bookingsTable,
224	      courtName: courtsTable.name,
225	      // bookings.coachId stores the coach's Clerk userId (text), so we join
226	      // coaches.userId — not coaches.id. The select picks both: numeric coach
227	      // table id (used for /coach/:id deep links) and display name.
228	      coachInternalId: coachesTable.id,
229	      coachName: coachesTable.name,
230	      // Joins coach_reviews and reviews on bookingId — both have unique
231	      // constraints on bookingId so each LEFT JOIN yields ≤ 1 match. We
232	      // surface id/rating/comment for both so the dashboard can render the
233	      // review in-place and pass them into the edit dialog without refetch.
234	      coachReviewId: coachReviewsTable.id,
235	      coachReviewRating: coachReviewsTable.rating,
236	      coachReviewComment: coachReviewsTable.comment,
237	      courtReviewId: reviewsTable.id,
238	      courtReviewRating: reviewsTable.rating,
239	      courtReviewComment: reviewsTable.comment,
240	    })
241	    .from(bookingsTable)
242	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
243	    .leftJoin(coachesTable, eq(bookingsTable.coachId, coachesTable.userId))
244	    .leftJoin(coachReviewsTable, eq(coachReviewsTable.bookingId, bookingsTable.id))
245	    .leftJoin(reviewsTable, eq(reviewsTable.bookingId, bookingsTable.id))
246	    .$dynamic();
247	
248	  if (role === "admin") {
249	    if (conditions.length > 0) {
250	      query = query.where(and(...conditions));
251	    }
252	  } else {
253	    // "My bookings" — always scoped to the authenticated booker, regardless of
254	    // role. Owners use GET /api/owner/bookings for the facility-wide view.
255	    conditions.push(eq(bookingsTable.bookerUserId, userId));
256	    query = query.where(and(...conditions));
257	  }
258	
259	  const rows = await query;
260	
261	  // For each split booking, count paid participants (mirrors the split-status endpoint logic)
262	  const paidSlotsMap = new Map<number, number>();
263	  await Promise.all(
264	    rows
265	      .filter(r => r.booking.isSplit)
266	      .map(async r => {
267	        const [game] = await db.select({ id: gamesTable.id })
268	          .from(gamesTable)
269	          .where(eq(gamesTable.bookingId, r.booking.id));
270	        if (!game) { paidSlotsMap.set(r.booking.id, 0); return; }
271	        const participants = await db.select({ paymentStatus: gameParticipantsTable.paymentStatus })
272	          .from(gameParticipantsTable)
273	          .where(and(
274	            eq(gameParticipantsTable.gameId, game.id),
275	            eq(gameParticipantsTable.status, "joined"),
276	          ));
277	        const paid = participants.filter(p => p.paymentStatus === "paid").length;
278	        paidSlotsMap.set(r.booking.id, paid);
279	      })
280	  );
281	
282	  res.json(ListBookingsResponse.parse(rows.map(r => formatBooking(
283	    r.booking,
284	    r.courtName ?? undefined,
285	    paidSlotsMap.get(r.booking.id),
286	    r.coachInternalId != null && r.coachName != null
287	      ? { id: r.coachInternalId, name: r.coachName }
288	      : null,
289	    r.coachReviewId != null && r.coachReviewRating != null
290	      ? { id: r.coachReviewId, rating: r.coachReviewRating, comment: r.coachReviewComment ?? null }
291	      : null,
292	    r.courtReviewId != null && r.courtReviewRating != null
293	      ? { id: r.courtReviewId, rating: r.courtReviewRating, comment: r.courtReviewComment ?? null }
294	      : null,
295	  ))));
296	});
