298	// POST /bookings — supports both authenticated bookers and guests.
299	// No requireAuth: if the caller has a Clerk session, we associate the booking with their userId.
300	// If not, we treat it as a guest booking (bookerUserId=null) and generate a managementToken
301	// so the guest can later view/cancel via /api/guest/bookings/:token.
302	router.post("/bookings", async (req, res): Promise<void> => {
303	  const parsed = CreateBookingBody.safeParse(req.body);
304	  if (!parsed.success) {
305	    console.error("[bookings] validation failed:", JSON.stringify(req.body), parsed.error.flatten());
306	    res.status(400).json({ error: parsed.error.message, details: parsed.error.flatten() });
307	    return;
308	  }
309	
310	  const recurringGroupId =
311	    typeof req.body?.recurringGroupId === "string" && req.body.recurringGroupId.length > 0
312	      ? req.body.recurringGroupId
313	      : null;
314	
315	  const d0 = parsed.data.date;
316	  const dateStr0 = `${d0.getUTCFullYear()}-${String(d0.getUTCMonth() + 1).padStart(2, "0")}-${String(d0.getUTCDate()).padStart(2, "0")}`;
317	  const dayOfWeek = new Date(dateStr0 + "T00:00:00").getDay();
318	  const reqStart = parsed.data.startTime;
319	  const reqEnd = parsed.data.endTime;
320	  const reqStartMin = toMin(reqStart);
321	  const reqEndMin = toMin(reqEnd);
322	
323	  const [court] = await db.select().from(courtsTable).where(eq(courtsTable.id, parsed.data.courtId));
324	  if (!court) {
325	    res.status(404).json({ error: "Court not found" });
326	    return;
327	  }
328	
329	  // ── Working hours validation ────────────────────────────────────────────────
330	  if (court.workingHours) {
331	    try {
332	      const wh = JSON.parse(court.workingHours) as Record<string, { open: string; close: string; closed: boolean }>;
333	      const dayConfig = wh[String(dayOfWeek)];
334	      if (dayConfig) {
335	        if (dayConfig.closed) {
336	          res.status(400).json({ error: "Court is closed on this day", code: "COURT_CLOSED" });
337	          return;
338	        }
339	        const openMin = toMin(dayConfig.open ?? "07:00");
340	        const closeMin = toMin(dayConfig.close ?? "22:00");
341	        if (reqStartMin < openMin || reqEndMin > closeMin) {
342	          res.status(400).json({ error: "Requested time is outside court working hours", code: "OUTSIDE_WORKING_HOURS" });
343	          return;
344	        }
345	      }
346	    } catch {
347	      // malformed workingHours JSON — skip validation, allow booking
348	    }
349	  }
350	
351	  // ── Advance booking limit check ───────────────────────────────────────────
352	  if (court.facilityId) {
353	    const [facility] = await db
354	      .select({ advanceBookingEnabled: facilitiesTable.advanceBookingEnabled, advanceBookingLimit: facilitiesTable.advanceBookingLimit })
355	      .from(facilitiesTable)
356	      .where(eq(facilitiesTable.id, court.facilityId));
357	    if (facility?.advanceBookingEnabled && facility.advanceBookingLimit != null) {
358	      const days = daysUntilBooking(dateStr0);
359	      if (days > facility.advanceBookingLimit) {
360	        res.status(400).json({
361	          error: `Rezervaciją galima atlikti ne anksčiau kaip ${facility.advanceBookingLimit} d. iš anksto`,
362	          code: "ADVANCE_BOOKING_LIMIT_EXCEEDED",
363	        });
364	        return;
365	      }
366	    }
367	  }
368	
369	  // ── Compute server-side price using full pricing waterfall ──
370	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
371	  const { priceMap } = await buildDayPriceMap(parsed.data.courtId, dateStr0, defaultSlotPrice);
372	
373	  const slots = slotsBetween(reqStart, reqEnd);
374	  let courtPrice = 0;
375	  for (const slotStart of slots) {
376	    courtPrice += priceMap.get(slotStart) ?? defaultSlotPrice;
377	  }
378	
379	  const durationMinutes = reqEndMin - reqStartMin;
380	  const slotCount = Math.round(durationMinutes / 30);
381	  const bookerUserId = getCurrentUserId(req);
382	
383	  // ── Atomically check conflicts and insert within a serialized transaction ──
384	  // A PostgreSQL advisory lock (per court+date) blocks any concurrent booking attempt
385	  // for the same court on the same day, making the read-then-write conflict check atomic.
386	  class BookingConflictError extends Error {
387	    constructor(public readonly statusCode: number, public readonly body: any) {
388	      super("BookingConflict");
389	    }
390	  }
391	
392	  let booking: typeof bookingsTable.$inferSelect;
393	  try {
394	    booking = await db.transaction(async (tx) => {
395	      // Acquire exclusive advisory lock for this court+date combination.
396	      // Released automatically at end of transaction.
397	      const dateInt = parseInt(dateStr0.replace(/-/g, ""), 10);
398	      await tx.execute(sql`SELECT pg_advisory_xact_lock(${sql.raw(String(parsed.data.courtId))}::int, ${sql.raw(String(dateInt))}::int)`);
399	
400	      // ── Conflict check (inside lock) ──
401	      const [conflictingBookings, conflictingBlocked] = await Promise.all([
402	        tx.select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
403	          .from(bookingsTable)
404	          .where(and(
405	            eq(bookingsTable.courtId, parsed.data.courtId),
406	            eq(bookingsTable.date, dateStr0),
407	            or(
408	              eq(bookingsTable.status, "confirmed"),
409	              eq(bookingsTable.status, "blocked"),
410	              eq(bookingsTable.status, "awaiting_players"),
411	              and(
412	                eq(bookingsTable.status, "pending"),
413	                sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`
414	              )
415	            )
416	          )),
417	        tx.select({ startTime: courtBlockedSlotsTable.startTime, endTime: courtBlockedSlotsTable.endTime })
418	          .from(courtBlockedSlotsTable)
419	          .where(and(
420	            eq(courtBlockedSlotsTable.courtId, parsed.data.courtId),
421	            eq(courtBlockedSlotsTable.date, dateStr0),
422	          )),
423	      ]);
424	
425	      for (const b of conflictingBookings) {
426	        const bStart = toMin(b.startTime);
427	        const bEnd = toMin(b.endTime);
428	        if (reqStartMin < bEnd && reqEndMin > bStart) {
429	          throw new BookingConflictError(409, { error: "Requested time slot is not available", code: "SLOT_UNAVAILABLE" });
430	        }
431	      }
432	
433	      for (const b of conflictingBlocked) {
434	        const bStart = toMin(b.startTime);
435	        const bEnd = toMin(b.endTime);
436	        if (reqStartMin < bEnd && reqEndMin > bStart) {
437	          throw new BookingConflictError(409, { error: "Requested time slot is blocked", code: "SLOT_BLOCKED" });
438	        }
439	      }
440	
441	      // ── Equipment availability (inside lock, same consistent snapshot) ──
442	      let equipmentCost = 0;
443	      let validatedRentedItems: string | null = null;
444	      if (parsed.data.rentedItems) {
445	        try {
446	          const clientItems: Array<{ name: string; quantity?: number }> = JSON.parse(parsed.data.rentedItems);
447	          const courtEquipment: Array<{ name: string; pricePerSlot?: number; pricePerBooking?: number; stock: number }> =
448	            court.rentableItems ? JSON.parse(court.rentableItems) : [];
449	
450	          const existingBookings = await tx
451	            .select({ rentedItems: bookingsTable.rentedItems, startTime: bookingsTable.startTime, endTime: bookingsTable.endTime, status: bookingsTable.status })
452	            .from(bookingsTable)
453	            .where(and(eq(bookingsTable.courtId, parsed.data.courtId), eq(bookingsTable.date, dateStr0)));
454	          const bookedQty: Record<string, number> = {};
455	          for (const b of existingBookings) {
456	            if (!b.rentedItems || b.status === "cancelled") continue;
457	            const bStart = toMin(b.startTime);
458	            const bEnd = toMin(b.endTime);
459	            if (bEnd <= reqStartMin || bStart >= reqEndMin) continue;
460	            const items: Array<{ name: string; quantity: number }> = JSON.parse(b.rentedItems);
461	            for (const item of items) {
462	              bookedQty[item.name] = (bookedQty[item.name] ?? 0) + item.quantity;
463	            }
464	          }
465	
466	          const serverValidated: Array<{ name: string; pricePerSlot: number; quantity: number }> = [];
467	          for (const ci of clientItems) {
468	            const canonical = courtEquipment.find(e => e.name === ci.name);
469	            if (!canonical) continue;
470	            const pricePerSlot = canonical.pricePerSlot ?? canonical.pricePerBooking ?? 0;
471	            const qty = Math.max(1, Math.min(Math.floor(ci.quantity ?? 1), 20));
472	            const alreadyBooked = bookedQty[ci.name] ?? 0;
473	            if (alreadyBooked + qty > canonical.stock) {
474	              throw new BookingConflictError(409, {
475	                error: `Įranga "${ci.name}" nebepasiekiama: likę ${Math.max(0, canonical.stock - alreadyBooked)} vnt.`,
476	                code: "EQUIPMENT_UNAVAILABLE",
477	                item: ci.name,
478	                available: Math.max(0, canonical.stock - alreadyBooked),
479	              });
480	            }
481	            serverValidated.push({ name: canonical.name, pricePerSlot, quantity: qty });
482	            equipmentCost += pricePerSlot * qty * slotCount;
483	          }
484	          if (serverValidated.length > 0) validatedRentedItems = JSON.stringify(serverValidated);
485	        } catch (e) {
486	          if (e instanceof BookingConflictError) throw e;
487	          console.error("[bookings] equipment validation error:", e);
488	        }
489	      }
490	
491	      const totalPrice = courtPrice + equipmentCost;
492	
493	      // ── Insert inside the same transaction ──
494	      // Guests (no Clerk session) get a management_token so they can later view & cancel
495	      // their booking via /api/guest/bookings/:token. Authenticated users use their session.
496	      const managementToken = bookerUserId ? null : generateManagementToken();
497	
498	      const [inserted] = await tx.insert(bookingsTable).values({
499	        courtId: parsed.data.courtId,
500	        bookerUserId: bookerUserId ?? null,
501	        customerName: parsed.data.customerName,
502	        customerEmail: parsed.data.customerEmail,
503	        customerPhone: parsed.data.customerPhone ?? null,
504	        date: dateStr0,
505	        startTime: parsed.data.startTime,
